/** 
 * Queues an input buffer to the decoder. No buffers may be queued after an  {@link DecoderInputBuffer#isEndOfStream() end of stream} buffer has been queued.
 */
public void queueInputBuffer(DecoderInputBuffer inputBuffer){
  try {
    checkState(!inputStreamEnded,"Input buffer can not be queued after the input stream has ended.");
  } catch (IllegalStateException e) {
    // Log the exception and return early to prevent further processing
    Log.e("queueInputBuffer", "IllegalStateException: " + e.getMessage());
    return;
  }
  int offset=0;
  int size=0;
  if (inputBuffer.data != null && inputBuffer.data.hasRemaining()) {
    offset=inputBuffer.data.position();
    size=inputBuffer.data.remaining();
  }
  int flags=0;
  if (inputBuffer.isEndOfStream()) {
    inputStreamEnded=true;
    flags=MediaCodec.BUFFER_FLAG_END_OF_STREAM;
  }
  mediaCodec.queueInputBuffer(inputBufferIndex,offset,size,inputBuffer.timeUs,flags);
  inputBufferIndex=C.INDEX_UNSET;
  inputBuffer.data=null;
}
